const $=id=>document.getElementById(id);let catalog,selected,contextStations=[];
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function filterPlans(items,{query='',station='',category='',context=[]}={}){const q=normalize(query);return items.filter(p=>(!q||normalize(p.code+' '+p.description+' '+p.file).includes(q))&&(!station||p.stations.includes(station))&&(!category||p.category===category)&&(!context.length||p.stations.some(s=>context.includes(s))));}
async function load(){if(catalog)return catalog;const response=await fetch('tecnica/linea1/catalogo.json?v=66');if(!response.ok)throw Error('Catálogo no disponible');catalog=await response.json();for(const s of [...new Set(catalog.items.flatMap(p=>p.stations))].sort())$('technical-station').add(new Option(s,s));for(const c of [...new Set(catalog.items.map(p=>p.category))].sort())$('technical-category').add(new Option(c,c));$('technical-summary').textContent=catalog.indexEntries+' entradas del índice · '+catalog.pdfFiles+' PDF · '+catalog.pages+' páginas escaneadas. '+catalog.scope;return catalog;}
function showPlan(p){selected=p.id;for(const b of $('technical-list').children)b.setAttribute('aria-pressed',String(b.dataset.plan===selected));$('technical-title').textContent=p.code;$('technical-description').textContent=p.description;$('technical-metadata').textContent=p.category+' · '+p.pages+' página(s) · '+(p.indexNumber?'Índice nº '+p.indexNumber:'Documento adicional del ZIP');$('technical-scope').textContent=p.status+'. '+p.review+'.';$('technical-related').textContent='Estaciones mencionadas: '+(p.stations.join(', ')||'sin asociación inequívoca en el índice');$('technical-preview').src=p.preview;$('technical-preview').alt='Vista de referencia del plano '+p.code;$('technical-pdf').href=p.pdf;$('technical-pdf').textContent='Abrir PDF para ampliar · copia de consulta';$('technical-readings').hidden=!p.verifiedReadings;$('technical-readings-table').replaceChildren();for(const value of p.verifiedReadings||[]){const row=document.createElement('tr'),name=document.createElement('th'),data=document.createElement('td');name.scope='row';name.textContent=value.parameter;data.textContent=value.value;row.append(name,data);$('technical-readings-table').append(row);}$('technical-readings-scope').textContent=p.readingScope||'';$('technical-detail').hidden=false;}
function render(){if(!catalog)return;const items=filterPlans(catalog.items,{query:$('technical-search').value,station:$('technical-station').value,category:$('technical-category').value,context:contextStations});$('technical-count').textContent=items.length+' planos encontrados'+(contextStations.length?' · relacionados con '+contextStations.join(' / '):'');$('technical-list').replaceChildren();for(const p of items){const b=document.createElement('button');b.type='button';b.dataset.plan=p.id;b.setAttribute('aria-pressed',String(p.id===selected));const title=document.createElement('b'),desc=document.createElement('span');title.textContent=p.code;desc.textContent=p.category+' · '+(p.stations.join(' / ')||'Referencia general');b.append(title,desc);b.onclick=()=>showPlan(p);$('technical-list').append(b);}const first=items.find(p=>p.id===selected)||items[0];if(first)showPlan(first);else $('technical-detail').hidden=true;}
async function open(fromRoute=false){$('technical-dialog').showModal();$('technical-error').hidden=true;try{await load();$('technical-search').value='';$('technical-station').value='';$('technical-category').value='';contextStations=[];if(fromRoute){const s=window.metroViewState?.();if(s?.currentLine===1){const t=s.engine.trains.find(t=>t.id===s.selectedTrain),l=s.engine.lines[1];if(t){const previous=Math.max(0,Math.min(l.stations.length-1,t.target-t.direction));contextStations=[l.stations[previous].nombre,l.stations[t.target].nombre];}}}render();}catch(e){$('technical-error').hidden=false;$('technical-error').textContent='No se pudieron abrir los planos. Vuelve a intentarlo.';}}
if($('technical-open'))$('technical-open').onclick=()=>open();if($('route-plans'))$('route-plans').hidden=true;$('technical-close').onclick=()=>$('technical-dialog').close();for(const id of['technical-search','technical-station','technical-category'])$(id).addEventListener(id==='technical-search'?'input':'change',()=>{contextStations=[];render();});$('technical-all').onclick=()=>{contextStations=[];$('technical-search').value='';$('technical-station').value='';$('technical-category').value='';render();};
setInterval(()=>{const s=window.metroViewState?.();if($('route-plans'))$('route-plans').hidden=true;},500);
